sql.where:
AND d.deleted = 0

    AND d.declaration_no = #{q.declarationNo}


    AND (d.declaration_no LIKE CONCAT('%', #{q.keyword}, '%')
         OR d.taxpayer_name_snapshot LIKE CONCAT('%', #{q.keyword}, '%'))


    AND t.taxpayer_code = #{q.taxpayerCode}


    AND d.taxpayer_name_snapshot LIKE CONCAT('%', #{q.taxpayerName}, '%')


    AND d.declaration_type_id = #{q.declarationTypeId}


    AND d.status = #{q.status}


    AND d.period_start >= #{q.periodFrom}


    AND d.period_end <= #{q.periodTo}


    AND d.submitted_at >= #{q.submittedFrom}


    AND d.submitted_at <= #{q.submittedTo}


    AND d.created_by = #{q.createdBy}


    AND d.declared_amount >= #{q.minAmount}


    AND d.declared_amount <= #{q.maxAmount}


    AND d.created_by = #{q.scopeUserId}


    AND EXISTS (
        SELECT 1 FROM declaration_review rv
        WHERE rv.declaration_id = d.id AND rv.reviewer_id = #{q.reviewerId}
    )

mapper.select:
SELECT
FROM tax_declaration d JOIN taxpayer t ON t.id = d.taxpayer_id JOIN sys_user u ON u.id = d.created_by
LIMIT #{q.limit}
